/* From Uiverse.io by newbiners - Tags: notification */
.__UIV_SCOPE__ .notification {
  width: 250px;
  height: 60px;
  background: rgb(146, 146, 146);
  border-radius: 14px;
  font-size: 2.3em;
  font-weight: 700;
  color: black;
  text-shadow: 2px 2px yellow;
  text-align: center;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: center;
  -ms-flex-pack: center;
  justify-content: center;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  gap: 4px;
}

.__UIV_SCOPE__ .notification span {
  -webkit-animation: levelup 2s ease infinite;
  animation: levelup 2s ease infinite;
}

.__UIV_SCOPE__ .notification span:nth-child(2) {
  -webkit-animation-delay: 0.25s;
  animation-delay: 0.25s;
}

.__UIV_SCOPE__ .notification span:nth-child(3) {
  -webkit-animation-delay: 0.5s;
  animation-delay: 0.5s;
}

.__UIV_SCOPE__ .notification span:nth-child(4) {
  -webkit-animation-delay: 0.75s;
  animation-delay: 0.75s;
}

.__UIV_SCOPE__ .notification span:nth-child(5) {
  -webkit-animation-delay: 1s;
  animation-delay: 1s;
}

.__UIV_SCOPE__ .notification span:nth-child(6) {
  -webkit-animation-delay: 1.25s;
  animation-delay: 1.25s;
}

.__UIV_SCOPE__ .notification span:nth-child(7) {
  -webkit-animation-delay: 1.5s;
  animation-delay: 1.5s;
}

.__UIV_SCOPE__ .notification span:nth-child(8) {
  -webkit-animation-delay: 1.75s;
  animation-delay: 1.75s;
}

@-webkit-keyframes levelup {
  0%, 100% {
    -webkit-transform: translateY(10px);
    transform: translateY(10px);
  }

  50% {
    -webkit-transform: translateY(-10px);
    transform: translateY(-10px);
  }
}

@keyframes levelup {
  0%, 100% {
    -webkit-transform: translateY(10px);
    transform: translateY(10px);
  }

  50% {
    -webkit-transform: translateY(-10px);
    transform: translateY(-10px);
  }
}
